package devices

import (
	"encoding/json"
	"math"
	"os"
	"testing"
)

// TestWERGolden (SPEC-v2 I9, task D): WER equals jiwer 4.0.0 on the 3a
// normalization (spikes/openvino/common.py normalize) for self-composed
// cases; testdata/wer_golden.json is generated by testdata/wer_golden.py,
// which also cross-checks jiwer against 3a's own word_errors.
func TestWERGolden(t *testing.T) {
	b, err := os.ReadFile("testdata/wer_golden.json")
	if err != nil {
		t.Fatal(err)
	}
	var g struct {
		Jiwer string `json:"jiwer"`
		Cases []struct {
			Name     string  `json:"name"`
			Ref      string  `json:"ref"`
			Hyp      string  `json:"hyp"`
			WER      float64 `json:"wer"`
			RefWords int     `json:"ref_words"`
		} `json:"cases"`
	}
	if err := json.Unmarshal(b, &g); err != nil {
		t.Fatal(err)
	}
	if g.Jiwer != "4.0.0" || len(g.Cases) < 20 {
		t.Fatalf("golden file: jiwer %q, %d cases", g.Jiwer, len(g.Cases))
	}
	for _, c := range g.Cases {
		w, n := WER(c.Ref, c.Hyp)
		if n != c.RefWords || math.Abs(w-c.WER) > 1e-12 {
			t.Errorf("%s: WER %.12f over %d words, jiwer %.12f over %d", c.Name, w, n, c.WER, c.RefWords)
		}
	}
}

func TestWERNoReference(t *testing.T) {
	for _, ref := range []string{"", "  ", "?!… — “”", "’'"} {
		if w, n := WER(ref, "some words"); w != 0 || n != 0 {
			t.Errorf("WER(%q) = %v over %d words, want 0 over 0", ref, w, n)
		}
	}
	if w, n := WER("one two", ""); w != 1 || n != 2 {
		t.Errorf("empty hypothesis: %v over %d", w, n)
	}
}

func TestWERWords(t *testing.T) {
	got := werWords("It's the CPU’s L1-cache: 64B/line, Vigenère.")
	want := []string{"its", "the", "cpus", "l1", "cache", "64b", "line", "vigen", "re"}
	if len(got) != len(want) {
		t.Fatalf("words %q, want %q", got, want)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("words %q, want %q", got, want)
		}
	}
}
